package transport

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

// Expected value generated by the control plane's reference implementation;
// guards against the two sides drifting apart.
func TestSignMatchesServerImplementation(t *testing.T) {
	got := Sign("topsecret", "POST", "/v1/agents/heartbeat", "1700000000", []byte(`{"version":"0.1.0"}`))
	want := "90adc77fb5de34518816ad49c377679aca39b24582703c014adcba160602a029"
	if got != want {
		t.Errorf("Sign() = %s, want %s", got, want)
	}
}

func TestPostSignsRequest(t *testing.T) {
	var verified bool
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		expected := Sign("s3cret", r.Method, r.URL.Path, r.Header.Get("X-Timestamp"), body)
		if r.Header.Get("X-Agent-Id") != "agent-1" {
			t.Errorf("X-Agent-Id = %q", r.Header.Get("X-Agent-Id"))
		}
		if r.Header.Get("X-Signature") != expected {
			t.Errorf("signature mismatch")
		}
		verified = true
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	}))
	defer server.Close()

	client := &Client{BaseURL: server.URL, AgentID: "agent-1", Secret: "s3cret"}
	resp, err := client.Post("/v1/agents/heartbeat", map[string]string{"version": "0.1.0"})
	if err != nil {
		t.Fatal(err)
	}
	resp.Body.Close()
	if !verified {
		t.Error("server handler never ran")
	}
}
